int calculateFare({
  required double distanceKm,
  required int minutes,
  bool isNight = false,
}) {
  const baseFare = 15000; // Toman
  const perKm = 4500;
  const perMinute = 700;

  var fare = baseFare + (distanceKm * perKm).round() + minutes * perMinute;
  if (isNight) fare = (fare * 1.2).round();
  return roundUpToThousand(fare);
}

int roundUpToThousand(int amount) => (amount / 1000).ceil() * 1000;

String formatToman(int amount) {
  final digits = amount.toString();
  final out = StringBuffer();
  for (var i = 0; i < digits.length; i++) {
    if (i > 0 && (digits.length - i) % 3 == 0) out.write(',');
    out.write(digits[i]);
  }
  return '$out تومان';
}

void main() {
  final fare = calculateFare(distanceKm: 8.4, minutes: 22, isNight: true);
  print('کرایه: ${formatToman(fare)}');
}

