class Profile {
  final String fullName;
  final String? email; // optional
  final String? nationalCode; // optional
  const Profile({required this.fullName, this.email, this.nationalCode});
}

bool isValidNationalCode(String code) {
  if (!RegExp(r'^\d{10}$').hasMatch(code)) return false;
  final d = code.split('').map(int.parse).toList();
  var sum = 0;
  for (var i = 0; i < 9; i++) {
    sum += d[i] * (10 - i);
  }
  final r = sum % 11;
  return r < 2 ? d[9] == r : d[9] == 11 - r;
}

String summary(Profile p) {
  final email = p.email?.trim() ?? 'ثبت نشده';
  final code = p.nationalCode; // local copy so it can be promoted
  final status = code == null
      ? 'وارد نشده'
      : (isValidNationalCode(code) ? 'معتبر' : 'نامعتبر');
  return '${p.fullName} | ایمیل: $email | کد ملی: $status';
}

void main() {
  print(summary(const Profile(fullName: 'مریم احمدی')));
  print(summary(const Profile(fullName: 'رضا کریمی', nationalCode: '0012345679')));
}

