mixin IranianValidators {
  bool isValidMobile(String v) => RegExp(r'^09\d{9}$').hasMatch(v);
  bool isValidPostalCode(String v) => RegExp(r'^\d{10}$').hasMatch(v);
}
mixin FormValidation on FormModel { // needs `fields`
  final errors = <String>[];
  void checkRequired() => fields.forEach((name, value) {
        if (value.trim().isEmpty) errors.add('$name الزامی است');
      });
  void check(bool ok, String message) {
    if (!ok) errors.add(message);
  }
