  final String mobile, postalCode;
  @override
  Map<String, String> get fields => {'موبایل': mobile, 'کد پستی': postalCode};

  bool validate() {
    errors.clear();
    checkRequired();
    check(isValidMobile(mobile), 'موبایل باید ۱۱ رقم و با ۰۹ شروع شود');
    check(isValidPostalCode(postalCode), 'کد پستی باید ۱۰ رقم باشد');
    return errors.isEmpty;
  }
}

