int countPrimes(int limit) {
  var count = 0;
  for (var n = 2; n <= limit; n++) {
    var isPrime = true;
    for (var d = 2; d * d <= n; d++) {
      if (n % d == 0) { isPrime = false; break; }
    }
    if (isPrime) count++;
  }
  return count;
}

