import 'dart:convert';
import 'dart:io';

final orders = <Map<String, dynamic>>[];
final mobilePattern = RegExp(r'^09\d{9}$');

Future<void> handle(HttpRequest req) async {
  final res = req.response..headers.contentType = ContentType.json;
  try {
    switch ((req.method, req.uri.path)) {
      case ('GET', '/orders'):
        res.write(jsonEncode(orders));
      case ('POST', '/orders'):
        final body = jsonDecode(await utf8.decodeStream(req));
        if (body is! Map<String, dynamic> || body['total'] is! int ||
            !mobilePattern.hasMatch('${body['mobile']}')) {
          res..statusCode = HttpStatus.badRequest..write(jsonEncode({'error': 'total یا mobile نامعتبر است'}));
          break;
        }
        orders.add({...body, 'id': orders.length + 1});
        res..statusCode = HttpStatus.created..write(jsonEncode(orders.last));
      default:
        res.statusCode = HttpStatus.notFound;
    }
  } on FormatException {
    res.statusCode = HttpStatus.badRequest; // body was not valid JSON
  }
  await res.close();
}

Future<void> main() async =>
    (await HttpServer.bind(InternetAddress.anyIPv4, 8080)).listen(handle);

