enum Level { debug, info, warning, error }

class AppLogger {
  AppLogger(this.tag, {this.minLevel = Level.info, this.sink = print});
  final String tag;
  final Level minLevel;
  final void Function(String line) sink;
  static final _card = RegExp(r'\b(\d{4})\d{8}(\d{4})\b');
  static final _mobile = RegExp(r'\b(09\d{2})\d{4}(\d{3})\b');

  String _redact(String m) => m
      .replaceAllMapped(_card, (x) => '${x[1]}********${x[2]}')
      .replaceAllMapped(_mobile, (x) => '${x[1]}****${x[2]}');

  void _write(Level level, String message, [Object? error]) {
    if (level.index < minLevel.index) return;
    final time = DateTime.now().toIso8601String().substring(11, 19);
    final err = error == null ? '' : ' | $error';
    sink('$time ${level.name.toUpperCase()} [$tag] ${_redact(message)}$err');
  }

  void debug(String m) => _write(Level.debug, m);
  void info(String m) => _write(Level.info, m);
  void error(String m, Object e) => _write(Level.error, m, e);
}

void main() {
  final log = AppLogger('payment');
  log.debug('raw gateway response ...'); // below minLevel: dropped
  log.info('pay start card=1234567812345678 mobile=09121234567');
  log.error('pay failed order=A-1025', StateError('gateway timeout'));
}

