// Task: "normalize Iranian mobile numbers". Clarify first, out loud:
// Q: Which inputs? A: '09121234567', '+989121234567', '9121234567', Persian digits.
// Q: Invalid input? A: return null.
// Plan: 1) Persian digits -> Latin 2) strip spaces/dashes 3) unify prefix 4) validate.
String? normalizeMobile(String input) {
  const fa = '۰۱۲۳۴۵۶۷۸۹';
  var s = input;
  for (var i = 0; i < 10; i++) {
    s = s.replaceAll(fa[i], '$i');
  }
  s = s.replaceAll(RegExp(r'[\s-]'), '');
  if (s.startsWith('+98')) s = '0${s.substring(3)}';
  if (s.startsWith('0098')) s = '0${s.substring(4)}';
  if (s.length == 10 && s.startsWith('9')) s = '0$s';
  return RegExp(r'^09\d{9}$').hasMatch(s) ? s : null;
}

void main() {
  // Test the edge cases you asked about, then mention trade-offs.
  const inputs = ['+98 912 123 4567', '۰۹۱۲۱۲۳۴۵۶۷', '9121234567', '0912-abc'];
  for (final input in inputs) {
    print('$input -> ${normalizeMobile(input)}');
  }
}
